package com.termux.app.workspace;
import android.app.Application;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import java.util.concurrent.atomic.AtomicBoolean;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiProtocolTest {
 static JSONArray history()throws Exception{return new JSONArray().put(new JSONObject().put("role","user").put("text","В /sdcard/Download найди самый новый TXT и прочитай его"));}
 static WorkspaceStore.Session profile(){WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="read";p.localCheckPaths=false;return p;}
 static final String BAD="{\"tool\":\"list\",\"path\":\"/sdcard/Download\",\"filter\":\"txt\"}";
 @Test public void invalidFilterCanBeCorrectedThenModelListsReadsAndAnswers()throws Exception{
  int[] generation={0},runs={0};JSONArray h=history();String answer=LocalAiAgent.run(profile(),h,new AtomicBoolean(),(a,s,o)->{switch(generation[0]++){case 0:return new LocalAiAgent.Generation(BAD,"eos");case 1:assertTrue(a.getJSONObject(a.length()-1).getString("text").contains("TOOL_VALIDATION_ERROR"));assertTrue(a.getJSONObject(a.length()-1).getString("text").contains("extension"));return new LocalAiAgent.Generation("{\"tool\":\"list\",\"path\":\"/sdcard/Download\",\"filter\":\"text\",\"extension\":\"txt\",\"limit\":1}","eos");case 2:return new LocalAiAgent.Generation("{\"tool\":\"read\",\"path\":\"/sdcard/Download/latest.txt\"}","eos");default:assertTrue(a.getJSONObject(a.length()-1).getString("text").contains("actual contents"));return new LocalAiAgent.Generation("Read successfully","eos");}},r->{runs[0]++;if(r.getString("tool").equals("list")){assertEquals("text",r.getString("filter"));assertEquals("txt",r.getString("extension"));return "exit=0\n{\"entries\":[{\"type\":\"file\",\"path\":\"/sdcard/Download/latest.txt\"}]}";}assertEquals("/sdcard/Download/latest.txt",r.getString("path"));return "exit=0\nactual contents";},r->{throw new AssertionError();},new LocalAiSearchTest.Events(),t->{});assertEquals("Read successfully",answer);assertEquals(4,generation[0]);assertEquals(2,runs[0]);assertTrue(h.getJSONObject(1).getBoolean("repair"));assertEquals("failed",h.getJSONObject(1).getString("toolState"));
 }
 @Test public void schemaRetriesStopWithoutExecutingInvalidCalls()throws Exception{int[] n={0};String answer=LocalAiAgent.run(profile(),history(),new AtomicBoolean(),(a,s,o)->{n[0]++;return new LocalAiAgent.Generation(BAD,"eos");},r->{throw new AssertionError();},r->{throw new AssertionError();},new LocalAiSearchTest.Events(),t->{});assertEquals(3,n[0]);assertTrue(answer.contains("two retries"));assertTrue(answer.contains("not executed"));}
 @Test public void correctedWriteStillCannotBypassReadOnlyRights()throws Exception{int[] n={0};try{LocalAiAgent.run(profile(),history(),new AtomicBoolean(),(a,s,o)->new LocalAiAgent.Generation(n[0]++==0?BAD:"{\"tool\":\"write\",\"path\":\"/sdcard/Download/a\",\"text\":\"no\"}","eos"),r->{throw new AssertionError();},r->{throw new AssertionError();},new LocalAiSearchTest.Events(),t->{});fail();}catch(SecurityException expected){}assertEquals(2,n[0]);}
 @Test public void cachedReadLoopStopsAndMarksOnlyActualReuse()throws Exception{int[] n={0},runs={0};JSONArray h=history();String answer=LocalAiAgent.run(profile(),h,new AtomicBoolean(),(a,s,o)->{n[0]++;return new LocalAiAgent.Generation("{\"tool\":\"read\",\"path\":\"/sdcard/Download/file.txt\"}","eos");},r->{runs[0]++;return "exit=0\ncontents";},r->false,new LocalAiSearchTest.Events(),t->{});assertEquals(4,n[0]);assertEquals(1,runs[0]);assertTrue(answer.contains("Repeated-read loop stopped"));assertFalse(h.getJSONObject(1).getBoolean("toolCached"));assertTrue(h.getJSONObject(3).getBoolean("toolCached"));assertTrue(h.getJSONObject(5).getBoolean("toolCached"));}
 @Test public void proseContainingInvalidExampleIsNotPromotedToExecution()throws Exception{int[] n={0};LocalAiAgent.run(profile(),history(),new AtomicBoolean(),(a,s,o)->{n[0]++;return new LocalAiAgent.Generation("Example: "+BAD,"eos");},r->{throw new AssertionError();},r->false,new LocalAiSearchTest.Events(),t->{});assertEquals(1,n[0]);}
 @Test public void cancellationAfterFeedbackPreventsAnotherGeneration()throws Exception{AtomicBoolean cancel=new AtomicBoolean();int[] n={0};try{LocalAiAgent.run(profile(),history(),cancel,(a,s,o)->{n[0]++;return new LocalAiAgent.Generation(BAD,"eos");},r->{throw new AssertionError();},r->false,new LocalAiAgent.Events(){public void save(){}public void phase(String p,String d){}public void tool(JSONObject r,String s,String text){cancel.set(true);}},t->{});fail();}catch(java.util.concurrent.CancellationException expected){}assertEquals(1,n[0]);}
}
